insert into public.courses (slug, title, subject, credits, focus)
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 1, $j$1.1 The Four Gospels and the Birth of Jesus$j$, $j${"readings": [{"title": "Matthew 1 (King James Version)", "url": "/portal/bible/Matthew/1"}, {"title": "Luke 1 (King James Version)", "url": "/portal/bible/Luke/1"}, {"title": "Luke 2 (King James Version)", "url": "/portal/bible/Luke/2"}, {"title": "John 1 (King James Version)", "url": "/portal/bible/John/1"}], "body": "Read Matthew 1, Luke 1, Luke 2 and John 1 in the King James Version. Then read this lesson.\n\nThe New Testament opens with four Gospels: Matthew, Mark, Luke and John. The word gospel means good news. Each Gospel tells the story of Jesus Christ from a different point of view. Matthew writes to show that Jesus is the promised King and Messiah. Mark tells the story quickly and shows Jesus as the servant who acts. Luke, a physician, gives careful detail and shows Jesus as the Savior for all people. John shows Jesus as the eternal Word who is God. Matthew and Luke tell of His birth in Bethlehem to Mary, a virgin, and the angel told Joseph to call His name Jesus, because He would save His people from their sins.\n\nKey words: gospel, Messiah, virgin, Bethlehem, Savior.\n\nYour task: (1) Name the four Gospels and tell what the word gospel means. (2) Explain why the angel said to call Him Jesus (Matthew 1:21). (3) Tell what the angel told the shepherds in Luke 2:10 and 11.\n\nCourse area: Bible elective. Scripture is read from the King James Version.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "Bible elective", "script": "Welcome to BIB 102, New Testament Survey. In the Old Testament we followed a promise from Genesis to Malachi. Now we open the New Testament and see that promise fulfilled in a person, Jesus Christ.\n\nThe New Testament begins with four books called the Gospels. The word gospel means good news. Matthew, Mark, Luke and John do not give four different stories. They give four views of the same Savior, the way four people standing at different places might describe the same mountain.\n\nMatthew was written with Jewish readers in mind. It begins with the family line of Jesus to show that He is the son of David and the son of Abraham, the promised King. Mark is the shortest and fastest Gospel, and it shows Jesus as the servant who is always on the move. Luke was written by a physician who investigated everything carefully, and he shows that Jesus came for all people. John shows us who Jesus really is, and its first verse says, In the beginning was the Word, and the Word was with God, and the Word was God. In John 1:14 we read, And the Word was made flesh, and dwelt among us.\n\nMatthew and Luke both tell how Jesus was born. An angel came to Mary, a young woman in Nazareth, and told her she would bear a son. Joseph was troubled, but the angel said to him in Matthew 1:21, thou shalt call his name JESUS: for he shall save his people from their sins. The name Jesus means the LORD saves.\n\nJesus was born in Bethlehem, just as Micah had promised. Shepherds were watching their flocks that night, and the angel told them in Luke 2:10 and 11, Fear not: for, behold, I bring you good tidings of great joy, which shall be to all people. For unto you is born this day in the city of David a Saviour, which is Christ the Lord.\n\nYour task is to name the four Gospels and tell what gospel means, explain why the angel said to call Him Jesus, and tell what the angel said to the shepherds. Then take the four question check.\n\nThe good news began in a manger and it is for all people. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$1.1 The Four Gospels and the Birth of Jesus$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 2, $j$1.2 The Baptism, Temptation and Teaching of Jesus$j$, $j${"readings": [{"title": "Matthew 3 (King James Version)", "url": "/portal/bible/Matthew/3"}, {"title": "Matthew 4 (King James Version)", "url": "/portal/bible/Matthew/4"}, {"title": "Matthew 5 (King James Version)", "url": "/portal/bible/Matthew/5"}, {"title": "Matthew 6 (King James Version)", "url": "/portal/bible/Matthew/6"}], "body": "Read Matthew 3, Matthew 4, Matthew 5 and Matthew 6 in the King James Version. Then read this lesson.\n\nWhen Jesus was about thirty years old, He went to the Jordan River to be baptized by John the Baptist. A voice from heaven said that He was the beloved Son. The Holy Spirit then led Him into the wilderness, where Satan tempted Him three times. Jesus answered each time with Scripture and said it is written. After this He began to preach that the kingdom of heaven was at hand and called twelve disciples to follow Him. His best known teaching is the Sermon on the Mount, which begins with the Beatitudes and includes the Lord's Prayer and the call to be the light of the world.\n\nKey words: baptism, temptation, disciple, kingdom of heaven, Sermon on the Mount.\n\nYour task: (1) Tell what the voice from heaven said at the baptism of Jesus. (2) Say what Jesus used to answer Satan and give one example. (3) Write Matthew 5:16 in your own words.\n\nCourse area: Bible elective. Scripture is read from the King James Version.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "Bible elective", "script": "Last time we saw the birth of Jesus. Today we move to the beginning of His public work, and it starts at the Jordan River. John the Baptist was preaching in the wilderness and calling people to repent. Jesus came to him to be baptized, and when He came up out of the water, the heavens opened and the Spirit of God came down like a dove. Then a voice from heaven said in Matthew 3:17, This is my beloved Son, in whom I am well pleased.\n\nRight after that, the Holy Spirit led Jesus into the wilderness. He fasted for forty days, and then Satan came to tempt Him three times. The first temptation was about hunger. Satan told Him to turn stones into bread. Jesus answered in Matthew 4:4, It is written, Man shall not live by bread alone, but by every word that proceedeth out of the mouth of God. Notice how Jesus answered every temptation. He said it is written. The Word of God is our best defense.\n\nAfter this, Jesus began to preach that the kingdom of heaven was at hand. He walked by the Sea of Galilee and called fishermen to follow Him, and He chose twelve disciples to be with Him. A disciple is a student who follows a teacher.\n\nThen came the Sermon on the Mount, the most famous teaching in the Gospels. Jesus began with the Beatitudes. Matthew 5:3 says, Blessed are the poor in spirit: for theirs is the kingdom of heaven. He taught about loving enemies, about giving in secret, and about prayer, and He gave His disciples a model prayer that begins, Our Father which art in heaven. He also said in Matthew 5:16, Let your light so shine before men, that they may see your good works, and glorify your Father which is in heaven.\n\nYour task is to tell what the voice from heaven said, say how Jesus answered Satan, and write Matthew 5:16 in your own words. Then take the four question check.\n\nWhen we know the Word, we can stand in the day of temptation. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$1.2 The Baptism, Temptation and Teaching of Jesus$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 3, $j$1.3 The Miracles and Parables of Jesus$j$, $j${"readings": [{"title": "Mark 4 (King James Version)", "url": "/portal/bible/Mark/4"}, {"title": "Mark 5 (King James Version)", "url": "/portal/bible/Mark/5"}, {"title": "Luke 15 (King James Version)", "url": "/portal/bible/Luke/15"}, {"title": "John 11 (King James Version)", "url": "/portal/bible/John/11"}], "body": "Read Mark 4, Mark 5, Luke 15 and John 11 in the King James Version. Then read this lesson.\n\nJesus taught with words and with power. His miracles showed that He had authority over sickness, nature, evil spirits and even death. He calmed a storm with a word, healed the sick, cast out demons and raised the dead, including Lazarus, whom He called from the tomb. He also taught in parables, which are short stories that use daily life to show a spiritual truth. In the parable of the prodigal son a father welcomes home a son who wasted everything, and it shows the love of God for sinners who come home.\n\nKey words: miracle, authority, parable, compassion, resurrection.\n\nYour task: (1) Tell what Jesus said to the wind and the sea. (2) Explain what a parable is and why Jesus used them. (3) Tell what the father did when he saw his son coming home (Luke 15:20).\n\nCourse area: Bible elective. Scripture is read from the King James Version.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "Bible elective", "script": "So far we have seen the birth of Jesus, His baptism and His teaching. Now we look at the two ways He showed who He was, through miracles and through parables.\n\nA miracle is an act of God's power that goes beyond what nature can do. Jesus did not perform miracles to entertain people. Each one showed that He had authority and that the kingdom of God had come. In Mark 4 Jesus and His disciples were crossing the Sea of Galilee when a great storm arose. Jesus was asleep in the boat, and the disciples woke Him in fear. He stood up, rebuked the wind and said in Mark 4:39, Peace, be still. And the wind ceased, and there was a great calm. The disciples marveled and asked, What manner of man is this, that even the wind and the sea obey him?\n\nIn Mark 5 He healed a woman who had been sick for twelve years and raised a girl from the dead. In John 11 He came to the tomb of His friend Lazarus, who had been dead four days. Jesus told Martha in John 11:25, I am the resurrection, and the life: he that believeth in me, though he were dead, yet shall he live. Then He called Lazarus out of the tomb, and he came out alive.\n\nJesus also taught in parables. A parable is a short story from everyday life that carries a spiritual truth. People who were ready to listen understood, and people who were not ready had to think about it. The most loved of the parables is the one about the prodigal son in Luke 15. A younger son took his inheritance, left home and wasted it all. When he came to himself, he decided to go home. Luke 15:20 says, But when he was yet a great way off, his father saw him, and had compassion, and ran, and fell on his neck, and kissed him. That is a picture of how God receives every sinner who returns.\n\nYour task is to tell what Jesus said to the wind, explain what a parable is, and tell what the father did. Then take the four question check.\n\nHe has power over every storm, and He welcomes every son and daughter home. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$1.3 The Miracles and Parables of Jesus$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 4, $j$1.4 The Cross and the Resurrection$j$, $j${"readings": [{"title": "Luke 23 (King James Version)", "url": "/portal/bible/Luke/23"}, {"title": "John 3 (King James Version)", "url": "/portal/bible/John/3"}, {"title": "John 19 (King James Version)", "url": "/portal/bible/John/19"}, {"title": "John 20 (King James Version)", "url": "/portal/bible/John/20"}, {"title": "Matthew 28 (King James Version)", "url": "/portal/bible/Matthew/28"}], "body": "Read Luke 23, John 3, John 19, John 20 and Matthew 28 in the King James Version. Then read this lesson.\n\nThe Gospels give more space to the last week of Jesus than to any other part of His life. After He rode into Jerusalem, He was arrested, tried and sentenced to be crucified outside the city. On the cross He prayed for those who crucified Him, and He died for the sins of the world. He was buried in a borrowed tomb. On the first day of the week the tomb was found empty, and the risen Jesus appeared to Mary Magdalene and the disciples. Before He returned to heaven, He gave His followers the Great Commission to go and teach all nations.\n\nKey words: crucifixion, atonement, resurrection, empty tomb, Great Commission.\n\nYour task: (1) Tell what Jesus prayed on the cross (Luke 23:34). (2) Explain what John 3:16 says about why Jesus came. (3) Tell what the angel said at the empty tomb and what the Great Commission asks believers to do.\n\nCourse area: Bible elective. Scripture is read from the King James Version.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "Bible elective", "script": "We have come to the center of the Gospels. All four writers slow down when they reach the last week of Jesus, because the cross and the empty tomb are the heart of the good news.\n\nJesus knew what was coming. He had told His disciples that He would be handed over, crucified and raised on the third day. He had also told Nicodemus the reason in John 3:16, For God so loved the world, that he gave his only begotten Son, that whosoever believeth in him should not perish, but have everlasting life. The cross was not an accident. It was the plan of a loving God.\n\nAfter a night of arrest and trial, Jesus was sentenced to death and crucified outside Jerusalem at a place called Golgotha. While soldiers nailed Him to the cross, He prayed in Luke 23:34, Father, forgive them; for they know not what they do. In John 19:30 He said, It is finished, and He gave up His spirit. Joseph of Arimathaea, a follower, asked for His body, and Jesus was laid in a new tomb. The sins of the world had been carried to the cross.\n\nEarly on the first day of the week, Mary Magdalene came to the tomb and found the stone rolled away. Jesus met her and called her by name. In Matthew 28:6 the angel said, He is not here: for he is risen, as he said. Jesus appeared to Mary, to the disciples, and later to more than five hundred people at one time. The resurrection proved that His sacrifice was accepted and that death was defeated.\n\nBefore He went back to heaven, Jesus gave His followers a task that we call the Great Commission. In Matthew 28:19 He said, Go ye therefore, and teach all nations. And He gave a promise in Matthew 28:20, lo, I am with you alway, even unto the end of the world.\n\nYour task is to tell what Jesus prayed on the cross, explain what John 3:16 says about why Jesus came, and tell what the angel said and what the Great Commission asks. Then take the four question check and the Unit 1 quiz.\n\nThe tomb is empty, and the Savior is alive. Excellence, Faith, Purpose. I will see you in the next unit."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$1.4 The Cross and the Resurrection$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'assessment', 1, $j$Assessment 1: The Life of Jesus in the Gospels$j$, $j${"prompt": "Choose one event from this unit: the birth of Jesus, His baptism, the calming of the storm, the raising of Lazarus, the parable of the prodigal son, the crucifixion or the resurrection. Write one paragraph of 150 to 200 words. Tell what happened, quote at least one verse from the King James Version, and explain what the event teaches us about who Jesus is.", "rubric": "Total 100. Accurate account of the event: 30. Quotes a King James Version verse with the reference: 20. Explains what the event shows about Jesus: 30. Clear writing and correct conventions: 20."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'assessment' and title = $j$Assessment 1: The Life of Jesus in the Gospels$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'discussion', 1, $j$Discussion 1: Why the Good News Matters$j$, $j${"prompt": "The Gospels call the story of Jesus good news. Which part of His life or teaching in this unit speaks most to you, and why? Describe how it could change the way you think or act this week. Respond in 100 to 150 words."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'discussion' and title = $j$Discussion 1: Why the Good News Matters$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 1, $j$Check 1.1: The Four Gospels and the Birth of Jesus$j$, $j${"questions": [{"q": "What does the word gospel mean?", "options": ["Old law", "Holy book", "Ancient song", "Good news"]}, {"q": "Which Gospel writer was a physician?", "options": ["Luke", "John", "Mark", "Matthew"]}, {"q": "Why did the angel tell Joseph to call the child Jesus?", "options": ["He was born on a holy day", "It was a family name", "He would save His people from their sins", "He would become a king in Rome"]}, {"q": "In which town was Jesus born?", "options": ["Bethlehem", "Capernaum", "Jericho", "Nazareth"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 1.1: The Four Gospels and the Birth of Jesus$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{3,0,2,0}'::int[], array[$j$The word gospel means good news.$j$,$j$Luke was a physician and wrote with careful detail.$j$,$j$Matthew 1:21 says He shall save His people from their sins.$j$,$j$Jesus was born in Bethlehem, the city of David (Luke 2:4 to 7).$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 1.1: The Four Gospels and the Birth of Jesus$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 2, $j$Check 1.2: The Baptism, Temptation and Teaching of Jesus$j$, $j${"questions": [{"q": "Who baptized Jesus in the Jordan River?", "options": ["John the Baptist", "Peter", "Paul", "Andrew"]}, {"q": "What did the voice from heaven say at the baptism of Jesus?", "options": ["This is my beloved Son, in whom I am well pleased", "Follow me", "Peace be unto you", "Repent, for the kingdom is at hand"]}, {"q": "How did Jesus answer each temptation from Satan?", "options": ["He stayed silent", "He called on angels at once", "He quoted Scripture and said it is written", "He walked away without speaking"]}, {"q": "What is the name of Jesus' famous teaching that begins with the Beatitudes?", "options": ["The Upper Room Prayer", "The Parable of the Sower", "The Sermon on the Mount", "The Olivet Discourse"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 1.2: The Baptism, Temptation and Teaching of Jesus$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{0,0,2,2}'::int[], array[$j$John the Baptist baptized Jesus (Matthew 3:13 to 17).$j$,$j$Matthew 3:17 records the Father's words.$j$,$j$Jesus answered with the written Word of God (Matthew 4:4, 7 and 10).$j$,$j$Matthew 5 to 7 is called the Sermon on the Mount.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 1.2: The Baptism, Temptation and Teaching of Jesus$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 3, $j$Check 1.3: The Miracles and Parables of Jesus$j$, $j${"questions": [{"q": "What did Jesus say to the wind and the sea in Mark 4:39?", "options": ["Rise and walk", "Be thou clean", "Peace, be still", "Follow me"]}, {"q": "What is a parable?", "options": ["A prayer for the sick", "A list of laws", "A short story from everyday life that teaches a spiritual truth", "A song of praise"]}, {"q": "Who did Jesus raise from the dead after four days in the tomb?", "options": ["Jairus' daughter", "Stephen", "Lazarus", "The widow's son"]}, {"q": "What did the father do when he saw his son returning in the parable of the prodigal son?", "options": ["He demanded repayment", "He sent him away", "He waited inside the house", "He had compassion, ran and embraced him"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 1.3: The Miracles and Parables of Jesus$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{2,2,2,3}'::int[], array[$j$Jesus said, Peace, be still, and there was a great calm.$j$,$j$A parable uses an ordinary story to show a spiritual truth.$j$,$j$John 11 tells how Jesus raised Lazarus.$j$,$j$Luke 15:20 says the father had compassion, and ran, and fell on his neck.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 1.3: The Miracles and Parables of Jesus$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 4, $j$Check 1.4: The Cross and the Resurrection$j$, $j${"questions": [{"q": "What did Jesus pray on the cross in Luke 23:34?", "options": ["Send twelve legions of angels", "Let this cup pass from me", "Father, forgive them; for they know not what they do", "Remember me in your kingdom"]}, {"q": "According to John 3:16, why did God give His only begotten Son?", "options": ["Because He loved the world", "Because Israel had earned it", "Because the law required a king", "Because the temple was destroyed"]}, {"q": "What did the angel say at the empty tomb in Matthew 28:6?", "options": ["Go and sin no more", "Fear not, for I bring good tidings", "He is not here: for he is risen, as he said", "The kingdom is at hand"]}, {"q": "What does the Great Commission ask believers to do?", "options": ["Guard the tomb", "Rebuild the temple", "Go and teach all nations", "Keep the Passover"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 1.4: The Cross and the Resurrection$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{2,0,2,2}'::int[], array[$j$Jesus asked the Father to forgive those who crucified Him.$j$,$j$God so loved the world that He gave His Son.$j$,$j$The angel announced the resurrection of Jesus.$j$,$j$Matthew 28:19 says to go and teach all nations.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 1.4: The Cross and the Resurrection$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 5, $j$Unit Quiz 1: The Gospels and the Life of Christ$j$, $j${"questions": [{"q": "Which Gospel opens by saying, In the beginning was the Word?", "options": ["John", "Mark", "Matthew", "Luke"]}, {"q": "Where was Jesus born?", "options": ["Nazareth", "Jerusalem", "Bethlehem", "Capernaum"]}, {"q": "How many times did Satan tempt Jesus in the wilderness, and how did Jesus answer?", "options": ["Once, with silence", "Seven times, with miracles", "Three times, with Scripture", "Twice, with prayer"]}, {"q": "Which miracle shows that Jesus has power over death?", "options": ["Raising Lazarus", "Calming the storm", "Healing a blind man", "Feeding the five thousand"]}, {"q": "What did the prodigal son's father do when his son came home?", "options": ["He had compassion and welcomed him", "He sent him away", "He demanded repayment", "He ignored him"]}, {"q": "What is the Great Commission?", "options": ["Keep the Sabbath", "Wait in the upper room", "Rebuild Jerusalem", "Go and teach all nations"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Unit Quiz 1: The Gospels and the Life of Christ$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{0,2,2,0,0,3}'::int[], array[$j$John begins with the eternal Word, who is God.$j$,$j$Jesus was born in Bethlehem.$j$,$j$Jesus answered each temptation with it is written.$j$,$j$Jesus raised Lazarus after four days in the tomb (John 11).$j$,$j$The father ran, embraced and kissed his son (Luke 15:20).$j$,$j$Jesus told His followers to go and teach all nations.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Unit Quiz 1: The Gospels and the Life of Christ$j$ on conflict (item_id) do nothing;
