-- BIB 102 New Testament Survey, unit 1. Safe to run more than once.

alter table public.courses add column if not exists video_url text;

values ('bib-102', 'BIB 102 New Testament Survey', 'Bible', 1.0, $j$BIB 102 is a one credit survey of the New Testament in the King James Version. Students read the four Gospels, the book of Acts, the letters of Paul, the General Epistles and Revelation, learn the setting and message of each section, and trace the story of Jesus Christ, the birth of the church and the hope of His return. Every lesson includes a reading assignment, a video lesson script, a check quiz, and unit work in writing and discussion. The course ends with a final assessment and a final exam. Excellence, Faith, Purpose.$j$)
on conflict (slug) do nothing;

do $seed$
declare cid uuid;
begin
  select id into cid from public.courses where slug = 'bib-102';
  if cid is null then raise exception 'Run unit 1 first'; end if;
end
$seed$;
